// *****************************************************************************
// generate_asset_list.dart
// -----------------------------------------------------------------------------
// pubspec.yaml の `flutter: assets:` セクションを自動生成するツール。
//
// 過去問の図表画像は assets/<exam>/images/<season>/q<num>/*.png という
// 深い階層に約 3,100 枚格納されている。Flutter のアセット指定は
// 「指定したディレクトリの直下のファイル」しか拾わず再帰しないため、
// 画像を含むディレクトリを 1 つずつ列挙する必要がある。
// 手で書くのは非現実的なので、このツールで機械的に生成する。
//
// 使い方:
//   dart run tool/generate_asset_list.dart
//
// pubspec.yaml 内の
//   # ASSETS:BEGIN (generated by tool/generate_asset_list.dart)
//   # ASSETS:END
// で囲まれた範囲を書き換える。マーカーの外は触らない。
// *****************************************************************************

import 'dart:io';

const _beginMarker =
    '  # ASSETS:BEGIN (generated by tool/generate_asset_list.dart)';
const _endMarker = '  # ASSETS:END';

/// ディレクトリ列挙ではなくファイル単体で登録するアセット
const _standaloneAssets = <String>[
  'assets/words.json',
  'assets/privacypolicy.txt',
  'assets/it_passport/questions.json',
  'assets/fe/questions.json',
  'assets/ap/questions.json',
];

void main() {
  final assetsDir = Directory('assets');
  if (!assetsDir.existsSync()) {
    stderr.writeln('assets/ が見つかりません。プロジェクトルートで実行してください。');
    exit(1);
  }

  // 画像が 1 枚でも直接入っているディレクトリだけを集める
  final imageDirs = <String>{};
  for (final entity in assetsDir.listSync(recursive: true)) {
    if (entity is! File) continue;
    final path = entity.path.replaceAll(r'\', '/');
    if (!path.toLowerCase().endsWith('.png') &&
        !path.toLowerCase().endsWith('.jpg') &&
        !path.toLowerCase().endsWith('.jpeg')) {
      continue;
    }
    // フォントディレクトリ配下の画像は fonts: セクションで扱うため対象外
    if (path.startsWith('assets/fonts/')) continue;
    imageDirs.add('${path.substring(0, path.lastIndexOf('/'))}/');
  }

  final sorted = imageDirs.toList()..sort();

  final lines = <String>[
    _beginMarker,
    '  assets:',
    for (final asset in _standaloneAssets) '    - $asset',
    for (final dir in sorted) '    - $dir',
    _endMarker,
  ];

  final pubspec = File('pubspec.yaml');
  final original = pubspec.readAsLinesSync();
  final begin = original.indexOf(_beginMarker);
  final end = original.indexOf(_endMarker);
  if (begin < 0 || end < 0 || end < begin) {
    stderr.writeln('pubspec.yaml に ASSETS:BEGIN / ASSETS:END マーカーが見つかりません。');
    exit(1);
  }

  final updated = [
    ...original.sublist(0, begin),
    ...lines,
    ...original.sublist(end + 1),
  ];
  pubspec.writeAsStringSync('${updated.join('\n')}\n');

  stdout.writeln('pubspec.yaml を更新しました: '
      '単体 ${_standaloneAssets.length} 件 / 画像ディレクトリ ${sorted.length} 件');
}
